/**
 * Helium10 SoftZilla Domain Switcher - Background Service Worker
 * Clean, working version without corrupted webpack code
 */

const DOMAIN_STORAGE_KEY = "ht_custom_domain";
const DOMAIN_REFRESH_TIME_KEY = "ht_linked_domain_updated_at";
const ACCOUNT_SYNC_KEYS = ["accountId", "isUserLogged", "unreadAlerts"];
const DEFAULT_DOMAIN = null;
let suppressInstallTab = false;
let queuedDomainSwitch = Promise.resolve();

function getSoftzillaDomain(url) {
  try {
    const host = new URL(url).hostname.toLowerCase();
    if (host === "__H10_PROXY_HOST__") return "ht01";
    const match = host.match(/^(ht\d+)\.amztoolsconsultant\.com$/i);
    return match ? match[1].toLowerCase() : null;
  } catch (e) {
    return null;
  }
}

async function resetExtensionAccountState() {
  // Keep user preferences in sync storage, but remove account identity there
  // and clear every account cache/token kept by the extension locally.
  await chrome.storage.local.clear();
  if (chrome.storage.session?.clear) {
    await chrome.storage.session.clear();
  }
  await chrome.storage.sync.remove(ACCOUNT_SYNC_KEYS);
}

// Keep one shared account, but ensure that the most recently refreshed htXX
// tab wins even when another account tab finishes loading later.
function switchToLatestDomain(domain, refreshTime = Date.now()) {
  if (!/^ht\d+$/.test(domain || "")) return;
  const eventTime = Number.isFinite(refreshTime) ? refreshTime : Date.now();
  queuedDomainSwitch = queuedDomainSwitch.then(async () => {
    const stored = await chrome.storage.local.get([DOMAIN_STORAGE_KEY, DOMAIN_REFRESH_TIME_KEY]);
    const storedTime = Number(stored[DOMAIN_REFRESH_TIME_KEY]) || 0;
    if (eventTime < storedTime) return;
    const previousDomain = stored[DOMAIN_STORAGE_KEY];
    if (previousDomain && previousDomain !== domain) {
      await resetExtensionAccountState();
    }
    await chrome.storage.local.set({
      [DOMAIN_STORAGE_KEY]: domain,
      [DOMAIN_REFRESH_TIME_KEY]: eventTime,
    });
  }).catch(() => undefined);
}

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status !== "loading") return;
  const domain = getSoftzillaDomain(changeInfo.url || tab.url);
  if (domain) switchToLatestDomain(domain);
});

// Do not register an automatic uninstall survey or redirect URL.
// The bundled vendor code calls this API during service-worker startup.
try {
  chrome.runtime.setUninstallURL = () => undefined;
} catch (e) {
  // Ignore browsers that expose this API as read-only.
}

// Global error handlers for "No SW" and context invalidated errors
try {
  self.addEventListener("error", (event) => {
    if (event.message && (event.message.includes("No SW") || event.message.includes("Extension context"))) {
      event.preventDefault();
      return false;
    }
  });
} catch (e) {
  // Silent catch
}

// Initialize storage with default domain if not set
chrome.runtime.onInstalled.addListener((details) => {
  // The bundled vendor listener opens its fixed signup URL on first install.
  // Do not send a new member to ht01 before their assigned domain is known.
  suppressInstallTab = details?.reason === chrome.runtime.OnInstalledReason.INSTALL;
  // Chrome reports Reload for an unpacked extension as an update lifecycle
  // event. Start with no account/cache state after that package reload.
  if (details?.reason === chrome.runtime.OnInstalledReason.UPDATE) {
    resetExtensionAccountState().catch(() => undefined);
  }
  chrome.storage.local.get([DOMAIN_STORAGE_KEY], (result) => {
  });
});

// Get current custom domain
function getCustomDomain() {
  return new Promise((resolve) => {
    try {
      chrome.storage.local.get([DOMAIN_STORAGE_KEY], (result) => {
        const domain = result[DOMAIN_STORAGE_KEY];
        if (domain && /^ht\d+$/.test(domain)) {
          resolve(domain);
        } else {
          resolve(null);
        }
      });
    } catch (e) {
      resolve(null);
    }
  });
}

// Replace URLs with custom domain
function replaceUrl(url, domain) {
  if (!url || typeof url !== "string") return url;
  const baseUrl = "__H10_PROXY_ORIGIN__";
  return url
    .replace(/https?:\/\/re-cdn\.helium10\.com/gi, baseUrl + "/__re-cdn")
    .replace(/https?:\/\/(?:members\.)?helium10\.com/gi, baseUrl)
    .replace(/https?:\/\/(?:members\.)?h10\.com\.cn/gi, baseUrl)
    .replace(/https?:\/\/(?:members|ht\d+)\.amztoolsconsultant\.com/gi, baseUrl);
}

// Patch chrome.tabs.create to intercept and rewrite URLs
const originalCreate = chrome.tabs.create;
chrome.tabs.create = function(createProperties, callback) {
  if (suppressInstallTab) {
    suppressInstallTab = false;
    if (typeof callback === "function") callback();
    return;
  }
  if (createProperties && createProperties.url && typeof createProperties.url === "string") {
    if (createProperties.url.match(/helium10\.com|h10\.com\.|h10\.|amztoolsconsultant\.com/i)) {
      getCustomDomain().then((domain) => {
        const newUrl = replaceUrl(createProperties.url, domain);
        createProperties.url = newUrl;
        originalCreate.call(this, createProperties, callback);
      });
      return;
    }
  }
  return originalCreate.call(this, createProperties, callback);
};

// Patch chrome.tabs.update to intercept and rewrite URLs
const originalUpdate = chrome.tabs.update;
chrome.tabs.update = function(tabId, updateProperties, callback) {
  if (updateProperties && updateProperties.url && typeof updateProperties.url === "string") {
    if (updateProperties.url.match(/helium10\.com|h10\.com\.|h10\.|amztoolsconsultant\.com/i)) {
      getCustomDomain().then((domain) => {
        const newUrl = replaceUrl(updateProperties.url, domain);
        updateProperties.url = newUrl;
        originalUpdate.call(this, tabId, updateProperties, callback);
      });
      return;
    }
  }
  return originalUpdate.call(this, tabId, updateProperties, callback);
};

// Patch fetch in service worker context
const originalFetch = globalThis.fetch || fetch;
globalThis.fetch = async function(...args) {
  let [resource, init] = args;
  let domain = null;

  try {
    domain = await getCustomDomain();
  } catch (e) {
    // If storage fails, leave the domain unresolved.
  }

  // Rewrite the resource if it's a string URL
  if (typeof resource === "string") {
    if (resource.match(/helium10\.com|h10\.com\.|h10\./i)) {
      resource = replaceUrl(resource, domain);
    } else if (resource.includes("amztoolsconsultant.com")) {
      resource = replaceUrl(resource, domain);
    }
  } 
  // Handle Request objects
  else if (resource instanceof Request) {
    const url = resource.url;
    if (url.match(/helium10\.com|h10\.com\.|amztoolsconsultant\.com/i)) {
      const newUrl = replaceUrl(url, domain);
      resource = new Request(newUrl, {
        method: resource.method,
        headers: resource.headers,
        body: resource.body,
        mode: resource.mode,
        credentials: resource.credentials,
        cache: resource.cache,
        redirect: resource.redirect,
        referrer: resource.referrer,
        integrity: resource.integrity
      });
    }
  }

  // Add credentials for auth endpoints
  if (typeof resource === "string" && (resource.includes("/auth") || resource.includes("/check-login"))) {
    init = init || {};
    init.credentials = "include";
  }

  return originalFetch.call(this, resource, init);
};

// Handle messages from content scripts
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  try {
    if (request.type === "CLEAR_LINKED_ACCOUNT") {
      resetExtensionAccountState().then(() => {
        sendResponse({ cleared: true });
      }).catch((error) => {
        sendResponse({ cleared: false, error: error?.message });
      });
      return true;
    } else if (request.type === "LINKED_DOMAIN_REFRESHED") {
      const domain = getSoftzillaDomain(sender.tab?.url || request.url);
      if (domain) {
        switchToLatestDomain(domain, request.refreshTime);
        sendResponse({ received: true, domain });
      } else {
        sendResponse({ received: false });
      }
    } else if (request.type === "AUTH_STATUS_CHANGED") {
      chrome.storage.local.set({
        "ht_user_logged_in": request.isLoggedIn,
        "ht_login_status_time": request.timestamp || Date.now()
      });
      sendResponse({ received: true });
    } else if (request.type === "GET_DOMAIN") {
      getCustomDomain().then((domain) => {
        sendResponse({ domain: domain });
      });
      return true; // Keep channel open for async response
    }
  } catch (e) {
    console.error("[BG] Message handling error:", e);
    sendResponse({ error: e.message });
  }
  return true;
});

